package com.aistock.prediction.verification;
import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import com.sun.net.httpserver.HttpServer;import java.net.InetSocketAddress;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class VerificationMarketClientTest {
 final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 JsonNode snapshot(){var r=mapper.createObjectNode();var i=r.putObject("input").put("instrumentId","SH600030").put("originDate","2026-09-21");var dates=i.putArray("targetDates");for(var d:List.of("2026-09-22","2026-09-23","2026-09-24","2026-09-25","2026-09-28"))dates.add(d);return r;}
 VerificationRequest request(){return new VerificationRequest(UUID.randomUUID(),LocalDate.parse("2026-09-23"),Instant.now().plusSeconds(90));}
 @Test void remainingTotalBudgetBoundsResponseBody()throws Exception{var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/market/realizations/prepare",ex->{ex.getRequestBody().readAllBytes();ex.sendResponseHeaders(200,0);ex.getResponseBody().write('{');ex.getResponseBody().flush();try{Thread.sleep(2000);}catch(InterruptedException e){Thread.currentThread().interrupt();}ex.close();});server.start();try{var client=new HttpVerificationMarketClient("http://127.0.0.1:"+server.getAddress().getPort(),"private-test",mapper,5,5);long start=System.nanoTime();assertThrows(BusinessException.class,()->client.prepare(request(),snapshot(),Instant.now().plusMillis(300)));assertTrue(Duration.ofNanos(System.nanoTime()-start).toMillis()<1500);}finally{server.stop(0);}}
 @Test void fixedVersionReadAndOperationIdentityAreRequired()throws Exception{
  for(boolean wrong:List.of(false,true)){var r=request();String version=UUID.randomUUID().toString();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
   server.createContext("/internal/v1/market/realizations/prepare",ex->{assertEquals("private-test",ex.getRequestHeaders().getFirst("X-Service-Token"));assertEquals("PREDICTION_VERIFICATION",ex.getRequestHeaders().getFirst("X-Market-Use-Purpose"));assertEquals(r.operationId().toString(),ex.getRequestHeaders().getFirst("X-Market-Use-Operation"));var b=mapper.readTree(ex.getRequestBody());assertEquals(r.operationId().toString(),b.path("operationId").asText());assertEquals(5,b.path("targetDates").size());var n=mapper.createObjectNode().put("code","OK");n.putObject("data").put("operationId",wrong?UUID.randomUUID().toString():r.operationId().toString()).put("state","AVAILABLE").put("versionId",version);var bytes=mapper.writeValueAsBytes(n);ex.sendResponseHeaders(200,bytes.length);ex.getResponseBody().write(bytes);ex.close();});
   server.createContext("/internal/v1/market/realizations/"+version,ex->{assertEquals("GET",ex.getRequestMethod());assertEquals("private-test",ex.getRequestHeaders().getFirst("X-Service-Token"));assertEquals("PREDICTION_VERIFICATION",ex.getRequestHeaders().getFirst("X-Market-Use-Purpose"));assertEquals(r.operationId().toString(),ex.getRequestHeaders().getFirst("X-Market-Use-Operation"));byte[] b=("{\"code\":\"OK\",\"data\":{\"realizationVersionId\":\""+version+"\"}}").getBytes(StandardCharsets.UTF_8);ex.sendResponseHeaders(200,b.length);ex.getResponseBody().write(b);ex.close();});server.start();
   try(var scope=com.aistock.prediction.marketuse.MarketUseContext.open(new com.aistock.prediction.marketuse.MarketUseClient.Request(r.operationId().toString(),"1",UUID.randomUUID().toString(),"PREDICTION_VERIFICATION",new com.aistock.common.marketlifecycle.MarketUseRecords.Selector("CURRENT_HEADS",null,null,List.of("SH600030"))),new com.aistock.prediction.marketuse.MarketUseClient.Receipt(UUID.randomUUID().toString(),"ACTIVE",List.of(UUID.randomUUID().toString())))){var client=new HttpVerificationMarketClient("http://127.0.0.1:"+server.getAddress().getPort(),"private-test",mapper,2,2);if(wrong)assertThrows(BusinessException.class,()->client.prepare(r,snapshot()));else assertEquals(version,client.prepare(r,snapshot()).path("realizationVersionId").asText());}finally{server.stop(0);}
  }
 }
 @Test void redirectsOversizeAndSlowBodyAreRejected()throws Exception{
  for(String mode:List.of("redirect","oversize","slow")){var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/market/realizations/prepare",ex->{ex.getRequestBody().readAllBytes();if(mode.equals("redirect")){ex.getResponseHeaders().set("Location","/elsewhere");ex.sendResponseHeaders(302,-1);}else if(mode.equals("oversize")){var b="x".repeat(131073).getBytes();ex.sendResponseHeaders(200,b.length);ex.getResponseBody().write(b);}else{ex.sendResponseHeaders(200,0);ex.getResponseBody().write('{');ex.getResponseBody().flush();try{Thread.sleep(3000);}catch(InterruptedException e){Thread.currentThread().interrupt();}}ex.close();});server.start();
   try{var client=new HttpVerificationMarketClient("http://127.0.0.1:"+server.getAddress().getPort(),"private-test",mapper,1,1);long start=System.nanoTime();assertThrows(BusinessException.class,()->client.prepare(request(),snapshot()));assertTrue(Duration.ofNanos(System.nanoTime()-start).toMillis()<2500);}finally{server.stop(0);}
  }
 }
 @Test void permanentRawMismatchIsNotCollapsedIntoRetryableNetworkFailure()throws Exception{for(boolean top:List.of(false,true)){var r=request();var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/internal/v1/market/realizations/prepare",ex->{ex.getRequestBody().readAllBytes();var n=mapper.createObjectNode().put("code",top?"REALIZATION_RAW_MISMATCH":"OK");if(top)n.putNull("data");else n.putObject("data").put("operationId",r.operationId().toString()).put("state","FAILED").putNull("versionId").put("errorCode","REALIZATION_RAW_MISMATCH");var bytes=mapper.writeValueAsBytes(n);ex.sendResponseHeaders(top?409:200,bytes.length);ex.getResponseBody().write(bytes);ex.close();});server.start();try{var client=new HttpVerificationMarketClient("http://127.0.0.1:"+server.getAddress().getPort(),"private-test",mapper,2,2);assertEquals("REALIZATION_RAW_MISMATCH",assertThrows(BusinessException.class,()->client.prepare(r,snapshot())).code());}finally{server.stop(0);}}}
 @Test void expiredLeasePreventsRequestEvenWithTotalBudgetRemaining() throws Exception {
  var server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);
  var calls=new java.util.concurrent.atomic.AtomicInteger();
  server.createContext("/",ex->{calls.incrementAndGet();ex.sendResponseHeaders(503,-1);ex.close();});
  server.start();
  try{
   var client=new HttpVerificationMarketClient("http://127.0.0.1:"+server.getAddress().getPort(),"private-test",mapper,2,2);
   var r=new VerificationRequest(UUID.randomUUID(),LocalDate.parse("2026-09-23"),Instant.now().minusSeconds(1));
   assertEquals("VERIFICATION_BUDGET_EXCEEDED",assertThrows(BusinessException.class,()->client.prepare(r,snapshot(),Instant.now().plusSeconds(10))).code());
   assertEquals(0,calls.get());
  }finally{server.stop(0);}
 }

}